import os
import socket
import ssl
import sys
import json
from datetime import datetime

def get_env_var(name, default=None):
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise ValueError(f"Required environment variable '{name}' is not set.")
    return value

def establish_secure_connection(host, port, cert_path, key_path=None):
    context = ssl.create_default_context(ssl.Purpose.SERVER_AUTH)
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED

    if cert_path:
        context.load_verify_locations(cafile=cert_path)

    if key_path:
        context.load_cert_chain(certfile=key_path)

    context.set_ciphers('ECDHE+AESGCM:DHE+AESGCM:ECDHE+CHACHA20:DHE+CHACHA20:!aNULL:!MD5:!DSS')

    try:
        sock = socket.create_connection((host, port), timeout=10)
        secure_sock = context.wrap_socket(sock, server_hostname=host)
        return secure_sock
    except socket.timeout:
        raise ConnectionError("Connection timed out while establishing secure link.")
    except socket.gaierror as e:
        raise ConnectionError(f"Failed to resolve host: {e}")
    except ssl.SSLError as e:
        raise ConnectionError(f"SSL handshake failed: {e}")
    except Exception as e:
        raise ConnectionError(f"Unexpected error during connection: {e}")

def send_status_report(secure_sock, report_data):
    try:
        secure_sock.sendall(json.dumps(report_data).encode('utf-8'))
        response = secure_sock.recv(4096)
        return json.loads(response.decode('utf-8'))
    except ssl.SSLError as e:
        raise ConnectionError(f"Data transmission failed due to SSL error: {e}")
    except socket.error as e:
        raise ConnectionError(f"Network error during data transmission: {e}")
    except json.JSONDecodeError:
        raise ValueError("Received invalid JSON response from server.")

def main():
    host = get_env_var("REMOTE_SERVER_HOST")
    port = int(get_env_var("REMOTE_SERVER_PORT", "443"))
    ca_cert_path = get_env_var("SSL_CA_CERT_PATH")
    client_cert_path = os.getenv("SSL_CLIENT_CERT_PATH")
    client_key_path = os.getenv("SSL_CLIENT_KEY_PATH")

    if not host or not port:
        sys.exit("Error: Host and port must be provided via environment variables.")

    secure_socket = None
    try:
        secure_socket = establish_secure_connection(host, port, ca_cert_path, client_cert_path)

        status_report = {
            "timestamp": datetime.utcnow().isoformat(),
            "status": "operational",
            "version": "1.0.0"
        }

        response = send_status_report(secure_socket, status_report)
        print("Status report sent and received successfully.")

    except ConnectionError as e:
        print(f"Connection failed: {e}", file=sys.stderr)
        sys.exit(1)
    except ValueError as e:
        print(f"Validation error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if secure_socket:
            try:
                secure_socket.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()
